import re

def remove_multiple_spaces(s: str) -> str:
    return re.sub(r'\s+', ' ', s).strip()

def is_Two_Alter(s: str) -> bool:
    if len(s) < 2:
        return False

    # Identify the two characters that should alternate
    unique_chars = set(s)
    if len(unique_chars) != 2:
        return False

    # Check if characters alternate
    for i in range(len(s) - 1):
        if s[i] == s[i + 1]:
            return False

    return True

def max_sub_array_sum(arr):
    if not arr:
        return 0

    max_sum = current_sum = arr[0]
    for num in arr[1:]:
        current_sum = max(num, current_sum + num)
        max_sum = max(max_sum, current_sum)
    return max_sum

def len_log(words):
    if not words:
        return 0
    return max(len(word) for word in words)

def count_nums(arr):
    def sum_signed_digits(n):
        s = str(n)
        # handle sign on first digit
        digits = []
        if s[0] == '-':
            digits.append(-int(s[1]))
            digits.extend(int(d) for d in s[2:])
        else:
            digits.extend(int(d) for d in s)
        return sum(digits)

    count = 0
    for num in arr:
        if sum_signed_digits(num) > 0:
            count += 1
    return count


